def design(feats):
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float); n, p = X.shape
    ids = list(feats.ids); types = list(feats.types)
    labs = sorted(set(feats.stratum))
    S = np.ones((n, 1)) if len(labs) < 2 else np.column_stack([np.ones(n)] + [np.array([s == l for s in feats.stratum], float) for l in labs[1:]])
    R = np.corrcoef(X, rowvar=False); R = np.nan_to_num(R)
    def ll(M):
        b = np.zeros(M.shape[1])
        for _ in range(30):
            mu = 1 / (1 + np.exp(-np.clip(M @ b, -30, 30)))
            w = mu * (1 - mu) + 1e-9
            H = M.T @ (M * w[:, None]) + 1e-6 * np.eye(M.shape[1])
            d = np.linalg.solve(H, M.T @ (y - mu)); b += d
            if np.abs(d).max() < 1e-7: break
        mu = np.clip(1 / (1 + np.exp(-np.clip(M @ b, -30, 30))), 1e-12, 1 - 1e-12)
        return float(np.sum(y * np.log(mu) + (1 - y) * np.log(1 - mu)))
    def base(cols, extra=()):
        return np.column_stack([S] + [X[:, j] for j in cols] + list(extra))
    deg = (np.abs(R) >= 0.6).sum(0) - 1
    hubs = [j for j in np.argsort(-deg)[:3] if deg[j] >= 3 and types[j] == 'clinical']
    def gain(cols, j):
        c = [k for k in cols if k != j]
        return 2 * (ll(base(c + [j])) - ll(base(c)))
    sel = []
    for step in range(MAX_DRIVERS):
        alpha = (0.05 if step == 0 else 0.02) / p
        ctx = sel + [h for h in hubs if all(abs(R[h, s]) < 0.6 for s in sel)]
        best, bj = 0, None
        for j in range(p):
            if j in sel or any(abs(R[j, s]) >= 0.6 for s in sel): continue
            g = gain(ctx, j)
            if g > best: best, bj = g, j
        if bj is None or stats.chi2.sf(best, 1) > alpha: break
        cl = [k for k in range(p) if abs(R[bj, k]) >= 0.6 and k not in sel] + [bj]
        gs = {k: gain(ctx, k) for k in set(cl)}; top = max(gs.values())
        cand = [k for k in gs if gs[k] >= top - 2]; hc = [k for k in cand if k in hubs]
        bj = hc[0] if hc else min(cand, key=lambda k: sum(max(0, gain(ctx + [k], m)) for m in cl if m != k))
        sel.append(bj)
    sel = [j for j in sel if len(sel) == 1 or stats.chi2.sf(gain(sel, j), 1) < 0.05 / p] if sel else sel
    if not sel:
        best, bp = 0, None; npair = p * (p - 1) / 2; l0 = ll(S)
        for a in range(p):
            for b in range(a + 1, p):
                if abs(R[a, b]) < 0.6: continue
                g = 2 * (ll(base([a, b])) - l0)
                if g > best: best, bp = g, (a, b)
        if bp and stats.chi2.sf(best, 2) < 0.05 / npair: sel = list(bp)
    prods = []
    l_m = ll(base(sel)); U = []
    for a in range(p):
        for b in range(a, p):
            if a != b and abs(R[a, b]) >= 0.6: continue
            z = X[:, a] * X[:, b]; z = (z - z.mean()) / (z.std() + 1e-9)
            U.append((abs(np.corrcoef(z, y)[0, 1]), a, b, z))
    U.sort(key=lambda t: -t[0]); m = p * (p + 1) / 2
    for _, a, b, z in U[:20]:
        mains = sorted(set(sel) | {a, b})
        g = 2 * (ll(base(mains, [z])) - ll(base(mains)))
        if stats.chi2.sf(g, 1) < 0.005 / m: prods.append((g, a, b))
    prods = sorted(prods, reverse=True)[:1]
    drv = [ids[j] for j in sel]
    for _, a, b in prods:
        for j in (a, b):
            if ids[j] not in drv: drv.append(ids[j])
    drv = drv[:MAX_DRIVERS]
    cols = list(drv) + [ids[h] for h in hubs if drv and ids[h] not in drv]
    return Design(drivers=tuple(drv), columns=tuple(cols), products=tuple((ids[a], ids[b]) for _, a, b in prods), loadings={})

